corrected_code:
app.get('/api/orders/invoice/:invoiceId', async (req, res) => {
  const params = {
    TableName: 'Invoices',
    Key: { invoiceId: req.params.invoiceId }
  };
  const data = await dynamoDb.get(params).promise();
  if (!data.Item || data.Item.customerId !== req.user.id) {
    return res.status(403).send('Forbidden');
  }
  res.json(data.Item);
});
